"""Minimal Byte Pair Encoding (BPE) tokenizer.

Tokens are SUBWORD pieces, not whole words:
  - common words stay whole  ->  "the"
  - rare/long words split   ->  "unhappiness" -> "un" "happi" "ness"

This is the same idea behind GPT / RoBERTa / LLaMA tokenizers.

Efficiency notes:
  - train() keeps a live list of piece-lists and updates them incrementally
    as each merge is learned, so the whole training run is O(merges * chars)
    instead of re-deriving every text from scratch each pass.
  - _apply_merges() applies each learned merge with a single forward scan,
    so encoding one sequence is O(merges * seq_len).
"""
import collections


class BPE:
    def __init__(self, vocab_size=256):
        self.vocab_size = vocab_size
        self.merges = []          # list of (a, b, new)
        self.itos = []           # id -> string
        self.stoi = {}           # string -> id
        self.pad_id = 0
        self.unk_id = 1

    def train(self, texts):
        # 1) initial vocab = special tokens + every character seen
        chars = set()
        for t in texts:
            chars.update(t)
        self.itos = ["<pad>", "<unk>"] + sorted(chars)
        self.stoi = {t: i for i, t in enumerate(self.itos)}
        self.pad_id = self.stoi["<pad>"]
        self.unk_id = self.stoi["<unk>"]
        self.merges = []

        # 2) keep a live piece-list per text; each merge updates them in place
        piece_lists = [list(t) for t in texts]

        while len(self.itos) < self.vocab_size:
            # count adjacent pairs across the current piece-lists
            pairs = collections.Counter()
            for pieces in piece_lists:
                for i in range(len(pieces) - 1):
                    pairs[(pieces[i], pieces[i + 1])] += 1

            merged = False
            for (a, b), _ in pairs.most_common():
                new = a + b
                if new not in self.stoi:
                    self.itos.append(new)
                    self.stoi[new] = len(self.itos) - 1
                    self.merges.append((a, b, new))
                    merged = True
                    # apply this one merge to every piece-list
                    for idx in range(len(piece_lists)):
                        piece_lists[idx] = self._merge_pair(
                            piece_lists[idx], a, b, new)
                    break
            if not merged:
                break

    @staticmethod
    def _merge_pair(pieces, a, b, new):
        """Single forward scan: replace every adjacent (a, b) with `new`."""
        out = []
        i, n = 0, len(pieces)
        while i < n:
            if i < n - 1 and pieces[i] == a and pieces[i + 1] == b:
                out.append(new)
                i += 2
            else:
                out.append(pieces[i])
                i += 1
        return out

    def _apply_merges(self, pieces):
        """Apply all learned merges in order (one forward scan each)."""
        for a, b, new in self.merges:
            pieces = self._merge_pair(pieces, a, b, new)
        return pieces

    def encode(self, text):
        """string -> list of token ids (subword pieces)."""
        pieces = self._apply_merges(list(text))
        return [self.stoi.get(p, self.unk_id) for p in pieces]

    def decode(self, ids):
        """list of token ids -> string (pieces re-joined)."""
        return "".join(self.itos[i] for i in ids
                       if i not in (self.pad_id, self.unk_id))

    @property
    def n_vocab(self):
        return len(self.itos)
